const pts = [[1,1.5],[2,2.8],[3,2.9],[4,4.5],[5,4.8],[6,6.0],[7,6.2],[8,7.0]];
const dots = pts.map(p => new Dot({ point: axes.c2p(p[0], p[1]), color: YELLOW }));

const line = new Polygon({ vertices: [axes.c2p(0,0), axes.c2p(10,8)], color: BLUE });
line.setStrokeWidth(4).setFillOpacity(0);
const meanDot = new Dot({ point: axes.c2p(5,4), color: RED });
scene.add(line, meanDot);
dots.forEach(d => scene.add(d));

function refit() {
  const data = dots.map(d => {
    const c = d.getCenter();
    const w = axes.p2c ? axes.p2c(c) : null;
    return w;
  });
  // fallback conversion using c2p of origin and unit
  const o = axes.c2p(0, 0), ux = axes.c2p(1, 0), uy = axes.c2p(0, 1);
  const sx = ux[0] - o[0], sy = uy[1] - o[1];
  const xy = dots.map(d => {
    const c = d.getCenter();
    return [(c[0] - o[0]) / sx, (c[1] - o[1]) / sy];
  });
  const n = xy.length;
  const mx = xy.reduce((a, p) => a + p[0], 0) / n;
  const my = xy.reduce((a, p) => a + p[1], 0) / n;
  let num = 0, den = 0;
  xy.forEach(p => { num += (p[0]-mx)*(p[1]-my); den += (p[0]-mx)*(p[0]-mx); });
  const m = den < 1e-9 ? 0 : num / den;
  const b = my - m * mx;
  // clip line to y range [0,8] and x range [0,10]
  let x0 = 0, x1 = 10;
  if (Math.abs(m) > 1e-9) {
    const xa = (0 - b) / m, xb = (8 - b) / m;
    const lo = Math.min(xa, xb), hi = Math.max(xa, xb);
    x0 = Math.max(0, lo); x1 = Math.min(10, hi);
  }
  if (x1 <= x0) { x0 = 0; x1 = 10; }
  line.setVertices([axes.c2p(x0, m*x0+b), axes.c2p(x1, m*x1+b)]);
  meanDot.moveTo(axes.c2p(mx, my));
}

dots.forEach(d => makeDraggable(d, scene, { onDrag: refit }));
refit();

const title = new Text({ text: 'Drag the points - the best-fit line updates', color: WHITE, fontSize: 28 });
title.moveTo([0, 3.6, 0]);
scene.add(title);

